TLM.f("Tempora/Epi2-4",{"officium":"Feria V infra Hebdomadam II post Epiphaniam","rule":["vide Epi2-0","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Epi2-0","from":{"Introitus":"Tempora/Epi2-0","Oratio":"Tempora/Epi2-0","Lectio":"Tempora/Epi2-0","Graduale":"Tempora/Epi2-0","Evangelium":"Tempora/Epi2-0","Offertorium":"Tempora/Epi2-0","Secreta":"Tempora/Epi2-0","Communio":"Tempora/Epi2-0","Postcommunio":"Tempora/Epi2-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 65:4"},{"k":"text","la":"Omnis terra adóret te, Deus, et psallat tibi: psalmum dicat nómini tuo, Altíssime."},{"k":"ref","la":"Ps 65:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra, psalmum dícite nómini ejus: date glóriam laudi ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Omnis terra adóret te, Deus, et psallat tibi: psalmum dicat nómini tuo, Altíssime."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui cœléstia simul et terréna moderáris: supplicatiónes pópuli tui cleménter exáudi; et pacem tuam nostris concéde tempóribus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:6-16"},{"k":"text","la":"Fratres: Habéntes donatiónes secúndum grátiam, quæ data est nobis, differéntes: sive prophetíam secúndum ratiónem fídei, sive ministérium in ministrándo, sive qui docet in doctrína, qui exhortátur in exhortándo, qui tríbuit in simplicitáte, qui præest in sollicitúdine, qui miserétur in hilaritáte. Diléctio sine simulatióne. Odiéntes malum, adhæréntes bono: Caritáte fraternitátis ínvicem diligéntes: Honóre ínvicem præveniéntes: Sollicitúdine non pigri: Spíritu fervéntes: Dómino serviéntes: Spe gaudéntes: In tribulatióne patiéntes: Oratióni instántes: Necessitátibus sanctórum communicántes: Hospitalitátem sectántes. Benedícite persequéntibus vos: benedícite, et nolíte maledícere. Gaudére cum gaudéntibus, flere cum fléntibus: Idípsum ínvicem sentiéntes: Non alta sapiéntes, sed humílibus consentiéntes."}],"Graduale":[{"k":"ref","la":"Ps 106:20-21"},{"k":"text","la":"Misit Dóminus verbum suum, et sanávit eos: et erípuit eos de intéritu eórum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus: et mirabília ejus fíliis hóminum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 148:2"},{"k":"text","la":"Laudáte Dóminum, omnes Angeli ejus: laudáte eum, omnes virtútes ejus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 2:1-11"},{"k":"text","la":"In illo témpore: Núptiæ factæ sunt in Cana Galilǽæ: et erat Mater Jesu ibi. Vocátus est autem et Jesus, et discípuli ejus ad núptias. Et deficiénte vino, dicit Mater Jesu ad eum: Vinum non habent. Et dicit ei Jesus: Quid mihi et tibi est, mulier? nondum venit hora mea. Dicit Mater ejus minístris: Quodcúmque díxerit vobis, fácite. Erant autem ibi lapídeæ hýdriæ sex pósitæ secúndum purificatiónem Judæórum, capiéntes síngulæ metrétas binas vel ternas. Dicit eis Jesus: Implete hýdrias aqua. Et implevérunt eas usque ad summum. Et dicit eis Jesus: Hauríte nunc, et ferte architriclíno. Et tulérunt. Ut autem gustávit architriclínus aquam vinum fáctam, et non sciébat unde esset, minístri autem sciébant, qui háuserant aquam: vocat sponsum architriclínus, et dicit ei: Omnis homo primum bonum vinum ponit: et cum inebriáti fúerint, tunc id, quod detérius est. Tu autem servásti bonum vinum usque adhuc. Hoc fecit inítium signórum Jesus in Cana Galilǽæ: et manifestávit glóriam suam, et credidérunt in eum discípuli ejus."}],"Offertorium":[{"k":"ref","la":"Ps 65:1-2; 65:16"},{"k":"text","la":"Jubiláte Deo, univérsa terra: psalmum dícite nómini ejus: veníte et audíte, et narrábo vobis, omnes qui timétis Deum, quanta fecit Dóminus ánimæ meæ, allelúja."}],"Secreta":[{"k":"text","la":"Oblata, Dómine, múnera sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 2:7; 2:8; 2:9; 2:10-11"},{"k":"text","la":"Dicit Dóminus: Implete hýdrias aqua et ferte architriclíno. Cum gustásset architriclínus aquam vinum factam, dicit sponso: Servásti bonum vinum usque adhuc. Hoc signum fecit Jesus primum coram discípulis suis."}],"Postcommunio":[{"k":"text","la":"Augeátur in nobis, quǽsumus, Dómine, tuæ virtútis operatio: ut divínis vegetáti sacraméntis, ad eórum promíssa capiénda, tuo múnere præparémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3267018770fb7d51":{"t":"Ps 65, 4, Ps 65, 1-2\n(Ps 65, 4) Sva zemlja neka ti se, Bože, klanja i neka ti pjeva. Neka pjeva imenu tvojemu, Višnji. (Ps 65, 1-2) Kličite Bogu svi narodi, pjevajte psalme njegovu imenu, hvalite njegovu slavu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 65, 4) Sva zemlja neka ti se, Bože, klanja i neka ti pjeva. Neka pjeva imenu tvojemu, Višnji."},"a3462e1391d73979":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji upravljaš i nebeskim i zemaljskim stvarima, milostivo usliši molbe puka svoga i podaj svoj mir u naša vremena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"db62595357017297":{"t":"Rim 12, 6-16\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Prema danoj nam milosti imamo različite darove. Tko ima dar proroštva, neka proriče u skladu s vjerovanjem; tko ima dar službe, neka služi; tko ima dar pouke, neka poučava; tko ima dar utjehe, neka tješi; tko dijeli, neka dijeli iskreno; tko upravlja, neka upravlja brižno; tko iskazuje milosrđe, neka to čini radosno. – Ljubav neka bude bez pretvaranja. Mrzite zlo, držite se dobra. Ljubite se među sobom bratskom ljubavlju, u časti dajte prednost jedan drugom. U brizi ne budite lijeni, budite gorljivi duhom u Gospodnjoj službi. U nadi se radujte, budite strpljivi u nevolji, postojani u molitvi. Pomažite svetima u potrebama, budite gostoljubivi. Blagoslivljajte one koji vas progone, blagoslivljajte, a nemojte proklinjati. Radujte se s onima koji se raduju, plačite s onima koji plaču. Budite jedne misli među sobom. Ne težite za visokim stvarima, nego se zadovoljite neznatnima."},"2988097cec4e6315":{"t":"Ps 106, 20-21\nPoslao je Gospodin svoju riječ i ozdravio ih i izbavio ih od propasti. Neka slavi Gospodina milosrđe njegovo i njegova čudesa na sinovima ljudskim.\n\nPs 148, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nHvalite Gospodina, svi anđeli njegovi, hvalite ga, sve čete njegove. <i>Aleluja</i>."},"9fb3d2b5b81f0585":{"t":"Iv 2, 1-11\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bio je u Kani Galilejskoj pir, a bila je ondje i Isusova majka. A na pir je bio pozvan Isus i njegovi učenici. Kad je nestalo vina, reče Isusu njegova majka: Vina nemaju. A Isus joj reče: Što je meni i tebi, ženo? Još nije došao moj čas. Tada njegova majka reče slugama: Što god vam rekne učinite. Ondje je bilo šest kamenih posuda, svaka od dvije do tri mjere, za pranje Židovima. Isus im reče: Napunite posude vodom. Oni ih napune do vrha. Tada im reče: Sad zagrabite i odnesite ravnatelju stola. Oni odnesu. Kad ravnatelj stola okusi vodu pretvorenu u vino a nije znao odakle je, dok su sluge koji zagrabiše vodu znali, ravnatelj stola zovne mladoženju i reče mu: Svatko iznosi najprije dobro vino, a kad se gosti ponapiju, onda slabije, ti si pak dobro vino čuvao do sada. Tako učini Isus prvo čudo u Kani Galilejskoj i objavi svoju slavu te su njegovi učenici vjerovali u njega."},"9c5bfd653e4c1dae":{"t":"Ps 65, 1-2 i 16\nKličite Bogu svi narodi, pjevajte psalme njegovu imenu. Dođite i slušajte svi koji se Boga bojite, pa ću vam pričati što je sve učinio mojoj duši, aleluja."},"ab9e9caa9afb15da":{"t":"Posveti, Gospodine, prikazane darove, a nas od ljage naših grijeha očisti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"ed31f706d3b5b6d2":{"t":"Iv 2, 7 i 8 i 9 i 10 i 11\nGospodin reče: »Napunite posude i odnesite ravnatelju stola.« A kad ovaj okusi vodu pretvorenu u vino, reče mladoženji: »Čuvao si dobro vino do sada.« To je prvo čudo što ga učini Isus pred svojim učenicima."},"d4c152e2efb613a2":{"t":"<i>Pomolimo se</i>.\nUmnoži u nama, molimo, Gospodine, djelovanje svoje moći da se, okrijepljeni božanskim otajstvima, po tvojem daru pripravimo da primimo ono što obećavaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
